// A connected Settings record wins over the sample below it, so the component
// shows what it is the moment you place it. Every input may be unconnected, so
// everything is guarded.
//
// Static Data hands out Models, a connected Record is a Model too, and another
// Function's output is a plain object. `plain` reads all three the same way.
const plain = (v) =>
  v && typeof v === 'object'
    ? (typeof v.get === 'function' && v.data ? { ...v.data } : { ...v })
    : {};
const asArray = (v) => (Array.isArray(v) ? v : v && Array.isArray(v.items) ? v.items : []);

const connected = plain(Inputs.Settings);
const sample = plain(asArray(Inputs.Fallback)[0]);
Outputs.Settings = Object.keys(connected).length > 0 ? connected : sample;

// -- The whole of the dirty tracking, in one node. ---------------------------
//
// Five things here are load-bearing, and each was a measured failure first.
//
// 1. A control's value output ALREADY HAS A VALUE before anything runs, and
//    making a connection copies it straight into the target. A Dropdown seeds
//    its own Value to its first default option and a Checkbox seeds Checked to
//    false, both in `initialize`; a Text Input does not, so its Value is still
//    undefined when the connection is made and the copy is skipped. So a field
//    is only believed once it has AGREED with the baseline at least once
//    (`settled` below). Without that the tracker mirrors a default the control
//    was never told to hold, never delivers the loaded value, and the page
//    opens on "3 unsaved changes" with two empty dropdowns and two unticked
//    boxes - which is exactly what the first render of this entry did.
// 2. `State` is this node's OWN output wired back to its own input, with "Run
//    on value change" UNTICKED (`runOnChange-in-State`). A Function keeps
//    nothing between runs, and this is the only memory it has. Ticked, the node
//    re-runs on the state it has just written - the shape that walks a stepper
//    to its last step on one click.
// 3. `Saves` and `Discards` are Counters, and a Counter arrives at 0 at load.
//    A Function whose inputs never arrive never runs, and then the FIRST press
//    is silently eaten as the boot run it never had.
// 4. `undefined` means "this control has not reported yet" and is NOT a
//    difference.
// 5. Every port is read and written by its literal name. The editor re-derives
//    a Function's ports by matching those names in the script text, so a value
//    reached through a variable key is a port the editor cannot see - and it
//    drops the port, and the connection with it, the next time the project is
//    opened.
//
// And the reason the value outputs MIRROR the live values rather than parking
// on the baseline: a Function output only publishes when it CHANGES. An output
// still holding the baseline it published at load cannot re-send it, so the
// SECOND Discard would do nothing at all while looking perfectly correct.

const FIELDS = ['Display Name', 'Email', 'Digest', 'Product Updates', 'Weekly Report', 'Theme'];

// Static Data hands out Models, a connected Record is a Model too, and another
// Function's output is a plain object. Read all three the same way.
const plain = (v) =>
  v && typeof v === 'object'
    ? (typeof v.get === 'function' && v.data ? { ...v.data } : { ...v })
    : {};

const loaded = plain(Inputs.Loaded);
const saves = Number(Inputs.Saves) || 0;
const discards = Number(Inputs.Discards) || 0;

const current = {
  'Display Name': Inputs.DisplayName,
  Email: Inputs.Email,
  Digest: Inputs.Digest,
  'Product Updates': Inputs.ProductUpdates,
  'Weekly Report': Inputs.WeeklyReport,
  Theme: Inputs.Theme
};

let state = Inputs.State;
if (!state || typeof state !== 'object' || state.source !== Inputs.Loaded) {
  // First run, or the host pushed a different record: what loaded IS the
  // baseline, and every field goes back to being unbelieved until it agrees
  // with it. `source` is the identity of the record and not its contents, so
  // an ordinary re-run does not keep resetting it.
  state = { source: Inputs.Loaded, baseline: { ...loaded }, saves: saves, discards: discards, settled: {} };
}

let reverting = false;
if (saves > state.saves) {
  // Save RE-BASELINES: what is on screen becomes what "unchanged" means from
  // here on, so the next Discard goes back to the saved values and not to the
  // ones this page was loaded with.
  const baseline = { ...state.baseline };
  for (const key of FIELDS) if (current[key] !== undefined) baseline[key] = current[key];
  state = { ...state, baseline: baseline, saves: saves };
}
if (discards > state.discards) {
  state = { ...state, discards: discards };
  reverting = true;
}

// What each control should show, and which controls are worth listening to.
const settled = { ...state.settled };
const show = {};
let learned = false;
for (const key of FIELDS) {
  const live = current[key];
  if (!settled[key] && live !== undefined && live === state.baseline[key]) {
    settled[key] = true;
    learned = true;
  }
  // An unsettled field is handed the baseline again on every run. That costs
  // nothing - an unchanged output publishes nothing - and it is what makes the
  // loaded record arrive whatever a control claimed about itself beforehand.
  show[key] = reverting || !settled[key] || live === undefined ? state.baseline[key] : live;
}
if (learned) state = { ...state, settled: settled };

Outputs.DisplayName = show['Display Name'];
Outputs.Email = show.Email;
Outputs.Digest = show.Digest;
Outputs.ProductUpdates = show['Product Updates'];
Outputs.WeeklyReport = show['Weekly Report'];
Outputs.Theme = show.Theme;

// On a revert the controls still hold the old text for one more frame, so the
// answer is known rather than measured: nothing is dirty.
const changed = reverting
  ? []
  : FIELDS.filter(
      (key) => settled[key] && current[key] !== undefined && current[key] !== state.baseline[key]
    );

Outputs.State = state;
Outputs.IsDirty = changed.length > 0;
Outputs.ChangeCount = changed.length;
Outputs.ChangedFields = changed.join(', ');
Outputs.Summary =
  changed.length === 0
    ? 'No unsaved changes'
    : changed.length === 1
    ? '1 unsaved change'
    : changed.length + ' unsaved changes';
Outputs.Values = { ...state.baseline, ...show };
